BEGIN FOR g IN (SELECT GRANTEE,PRIVILEGE FROM ALL_TAB_PRIVS WHERE OWNER=USER AND TABLE_NAME='CX_ANSWER_QUALITY_CREDENTIALS') LOOP EXECUTE IMMEDIATE 'REVOKE '||g.PRIVILEGE||' ON CX_ANSWER_QUALITY_CREDENTIALS FROM "'||REPLACE(g.GRANTEE,'"','""')||'"'; END LOOP; END;
/

